package com.abosultan.darbakmaps.ui;

import android.content.Context; import android.graphics.Bitmap; import android.graphics.Canvas; import android.graphics.Path; import android.widget.FrameLayout; import java.io.File; import java.util.ArrayList; import java.util.List; import org.mapsforge.core.graphics.Paint; import org.mapsforge.core.graphics.Style; import org.mapsforge.core.model.LatLong; import org.mapsforge.map.android.graphics.AndroidBitmap; import org.mapsforge.map.android.graphics.AndroidGraphicFactory; import org.mapsforge.map.android.util.AndroidUtil; import org.mapsforge.map.android.view.MapView; import org.mapsforge.map.datastore.MapDataStore; import org.mapsforge.map.layer.cache.TileCache; import org.mapsforge.map.layer.overlay.Marker; import org.mapsforge.map.layer.overlay.Polyline; import org.mapsforge.map.layer.renderer.TileRendererLayer; import org.mapsforge.map.reader.MapFile; import org.mapsforge.map.rendertheme.internal.MapsforgeThemes; import com.abosultan.darbakmaps.core.CoreContracts.LocationSnapshot; import com.abosultan.darbakmaps.core.CoreContracts.Place; import com.abosultan.darbakmaps.core.LiveLocationStore; import com.abosultan.darbakmaps.core.OfflineMapLocator; import com.abosultan.darbakmaps.core.SessionStore; import com.abosultan.darbakmaps.core.SqlitePlaceRepository; import com.abosultan.darbakmaps.core.SqliteTrackRecorder;
public final class OfflineMapView extends FrameLayout {
 private static final int RESTORE_TRACK_POINTS=4000,MAX_PLACE_MARKERS=500; private MapView mapView; private TileCache tileCache; private MapDataStore mapDataStore; private TileRendererLayer renderer; private Polyline trackOutline,activeTrack; private Marker vehicleMarker; private final List<Marker> placeMarkers=new ArrayList<>(); private File activeMap; private SessionStore sessionStore; private SqliteTrackRecorder trackStore; private SqlitePlaceRepository placeStore; private long lastFixTime; private boolean followedFirstFix; private LatLong lastTrackPoint; private float lastVehicleBearing=Float.NaN;
 private final Runnable gpsPump=new Runnable(){@Override public void run(){LocationSnapshot fix=LiveLocationStore.latest();if(mapView!=null&&fix.valid&&fix.timestampMs!=lastFixTime){lastFixTime=fix.timestampMs;LatLong position=new LatLong(fix.latitude,fix.longitude);if(!followedFirstFix){centerOn(position,(byte)15);followedFirstFix=true;}appendLiveTrack(position);updateVehicleMarker(position,fix.bearing);}postDelayed(this,750L);}};
 public OfflineMapView(Context c){super(c);sessionStore=new SessionStore(c);trackStore=new SqliteTrackRecorder(c);placeStore=new SqlitePlaceRepository(c);setBackgroundColor(0xFFE8E1CF);tryOpen(c);} public boolean hasMap(){return activeMap!=null;} public String activeMapName(){return activeMap==null?null:activeMap.getName();} public void zoomIn(){if(mapView!=null){byte z=mapView.getModel().mapViewPosition.getZoomLevel();if(z<20)mapView.setZoomLevel((byte)(z+1));}} public void zoomOut(){if(mapView!=null){byte z=mapView.getModel().mapViewPosition.getZoomLevel();if(z>3)mapView.setZoomLevel((byte)(z-1));}} public boolean recenterOnGps(){LocationSnapshot f=LiveLocationStore.latest();if(mapView==null||!f.valid)return false;centerOn(new LatLong(f.latitude,f.longitude),(byte)15);followedFirstFix=true;return true;} public boolean focusPlace(double lat,double lon){if(mapView==null)return false;centerOn(new LatLong(lat,lon),(byte)16);followedFirstFix=true;return true;}
 public boolean saveCurrentPlace(String category){LocationSnapshot f=LiveLocationStore.latest();if(!f.valid||placeStore==null)return false;String safe=category==null||category.length()==0?"other":category;try{long id=placeStore.save(new Place(0L,f.latitude,f.longitude,safe,null,null));if(id<=0)return false;if(mapView!=null)addPlaceMarker(new Place(id,f.latitude,f.longitude,safe,null,null));return true;}catch(RuntimeException e){return false;}}
 private void centerOn(LatLong p,byte min){mapView.setCenter(p);if(mapView.getModel().mapViewPosition.getZoomLevel()<min)mapView.setZoomLevel(min);} @Override protected void onAttachedToWindow(){super.onAttachedToWindow();removeCallbacks(gpsPump);post(gpsPump);}
 private void tryOpen(Context c){try{AndroidGraphicFactory.createInstance(c.getApplicationContext());List<File> maps=OfflineMapLocator.find(c);if(maps.isEmpty())return;activeMap=maps.get(0);mapView=new MapView(c);mapView.getMapScaleBar().setVisible(true);mapView.setBuiltInZoomControls(false);addView(mapView,new LayoutParams(LayoutParams.MATCH_PARENT,LayoutParams.MATCH_PARENT));tileCache=AndroidUtil.createTileCache(c,"darbak-mapcache",mapView.getModel().displayModel.getTileSize(),1f,mapView.getModel().frameBufferModel.getOverdrawFactor());mapDataStore=new MapFile(activeMap);renderer=new TileRendererLayer(tileCache,mapDataStore,mapView.getModel().mapViewPosition,AndroidGraphicFactory.INSTANCE);renderer.setXmlRenderTheme(MapsforgeThemes.MOTORIDER);mapView.getLayerManager().getLayers().add(renderer);createTrackLayers(c);restoreTrack();restorePlaceMarkers();SessionStore.Viewport s=sessionStore.restoreViewport();if(s!=null&&s.latitude>=-90&&s.latitude<=90&&s.longitude>=-180&&s.longitude<=180){mapView.setCenter(new LatLong(s.latitude,s.longitude));mapView.setZoomLevel((byte)Math.max(3,Math.min(20,s.zoom)));followedFirstFix=true;}else{mapView.setCenter(mapDataStore.boundingBox().getCenterPoint());mapView.setZoomLevel((byte)10);}}catch(Exception e){activeMap=null;if(mapView!=null){mapView.destroyAll();removeAllViews();mapView=null;}}}
 private void createTrackLayers(Context c){Paint o=AndroidGraphicFactory.INSTANCE.createPaint();o.setColor(TrackStyle.ACTIVE_TRACK_OUTLINE);o.setStyle(Style.STROKE);o.setStrokeWidth(DarbakUi.dp(c,(int)TrackStyle.ACTIVE_TRACK_OUTLINE_WIDTH_DP));trackOutline=new Polyline(o,AndroidGraphicFactory.INSTANCE);mapView.getLayerManager().getLayers().add(trackOutline);Paint p=AndroidGraphicFactory.INSTANCE.createPaint();p.setColor(TrackStyle.ACTIVE_TRACK);p.setStyle(Style.STROKE);p.setStrokeWidth(DarbakUi.dp(c,(int)TrackStyle.ACTIVE_TRACK_WIDTH_DP));activeTrack=new Polyline(p,AndroidGraphicFactory.INSTANCE);mapView.getLayerManager().getLayers().add(activeTrack);} private void restoreTrack(){if(trackStore==null||activeTrack==null||trackOutline==null)return;for(LocationSnapshot p:trackStore.recentPoints(RESTORE_TRACK_POINTS)){LatLong x=new LatLong(p.latitude,p.longitude);trackOutline.addPoint(x);activeTrack.addPoint(x);lastTrackPoint=x;}} private void restorePlaceMarkers(){if(placeStore==null||mapView==null)return;for(Place p:placeStore.all(MAX_PLACE_MARKERS))addPlaceMarker(p);} private void addPlaceMarker(Place p){if(mapView==null)return;Marker m=new Marker(new LatLong(p.latitude,p.longitude),createPlaceIcon(p.category),0,0);m.setBillboard(true);mapView.getLayerManager().getLayers().add(m);placeMarkers.add(m);mapView.getLayerManager().redrawLayers();}
 private org.mapsforge.core.graphics.Bitmap createPlaceIcon(String cat){int size=DarbakUi.dp(getContext(),34);Bitmap b=Bitmap.createBitmap(size,size,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);android.graphics.Paint p=new android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG);p.setStyle(android.graphics.Paint.Style.FILL);p.setColor(categoryColor(cat));float x=size/2f;c.drawCircle(x,x,x-DarbakUi.dp(getContext(),2),p);p.setStyle(android.graphics.Paint.Style.STROKE);p.setStrokeWidth(DarbakUi.dp(getContext(),2));p.setColor(0xFFFFFFFF);c.drawCircle(x,x,x-DarbakUi.dp(getContext(),4),p);p.setStyle(android.graphics.Paint.Style.FILL);p.setTextAlign(android.graphics.Paint.Align.CENTER);p.setTextSize(DarbakUi.dp(getContext(),17));p.setFakeBoldText(true);c.drawText(categoryGlyph(cat),x,x-(p.ascent()+p.descent())/2f,p);return new AndroidBitmap(b);} private static int categoryColor(String c){if(c==null)return 0xFF6D5B3E;if(c.contains("bird")||c.contains("summan"))return 0xFFB8860B;if(c.contains("water"))return 0xFF1976D2;if(c.contains("camp"))return 0xFF2E7D32;if(c.contains("fuel"))return 0xFFC62828;return 0xFF6D5B3E;} private static String categoryGlyph(String c){if(c==null)return "•";if(c.contains("bird")||c.contains("summan"))return "ط";if(c.contains("water"))return "م";if(c.contains("camp"))return "خ";if(c.contains("fuel"))return "و";return "•";}
 private void appendLiveTrack(LatLong p){if(activeTrack==null||trackOutline==null)return;if(lastTrackPoint!=null&&lastTrackPoint.sphericalDistance(p)<2)return;trackOutline.addPoint(p);activeTrack.addPoint(p);lastTrackPoint=p;if(mapView!=null)mapView.getLayerManager().redrawLayers();} private void updateVehicleMarker(LatLong p,float b){if(mapView==null)return;if(vehicleMarker==null){vehicleMarker=new Marker(p,createVehicleArrow(b),0,0);vehicleMarker.setBillboard(true);mapView.getLayerManager().getLayers().add(vehicleMarker);lastVehicleBearing=b;}else{vehicleMarker.setLatLong(p);if(Float.isNaN(lastVehicleBearing)||Math.abs(angleDelta(lastVehicleBearing,b))>=5){vehicleMarker.setBitmap(createVehicleArrow(b));lastVehicleBearing=b;}}mapView.getLayerManager().redrawLayers();}
 private org.mapsforge.core.graphics.Bitmap createVehicleArrow(float b){int size=DarbakUi.dp(getContext(),44);Bitmap base=Bitmap.createBitmap(size,size,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(base);android.graphics.Paint s=new android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG);s.setStyle(android.graphics.Paint.Style.FILL);s.setColor(0xDD111111);android.graphics.Paint f=new android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG);f.setStyle(android.graphics.Paint.Style.FILL);f.setColor(0xFFFFFFFF);android.graphics.Paint e=new android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG);e.setStyle(android.graphics.Paint.Style.STROKE);e.setStrokeWidth(DarbakUi.dp(getContext(),2));e.setColor(0xFF111111);float x=size/2f;Path a=new Path();a.moveTo(x,DarbakUi.dp(getContext(),3));a.lineTo(size-DarbakUi.dp(getContext(),8),size-DarbakUi.dp(getContext(),7));a.lineTo(x,size-DarbakUi.dp(getContext(),14));a.lineTo(DarbakUi.dp(getContext(),8),size-DarbakUi.dp(getContext(),7));a.close();c.save();c.rotate(b,x,x);c.translate(DarbakUi.dp(getContext(),1),DarbakUi.dp(getContext(),2));c.drawPath(a,s);c.translate(-DarbakUi.dp(getContext(),1),-DarbakUi.dp(getContext(),2));c.drawPath(a,f);c.drawPath(a,e);c.restore();return new AndroidBitmap(base);} private static float angleDelta(float f,float t){return(t-f+540)%360-180;} private void saveViewport(){if(mapView==null||sessionStore==null)return;LatLong c=mapView.getModel().mapViewPosition.getCenter();if(c!=null)sessionStore.saveViewport(c.latitude,c.longitude,mapView.getModel().mapViewPosition.getZoomLevel());}
 @Override protected void onDetachedFromWindow(){removeCallbacks(gpsPump);saveViewport();if(mapView!=null){mapView.destroyAll();mapView=null;}if(mapDataStore!=null){mapDataStore.close();mapDataStore=null;}if(trackStore!=null){trackStore.close();trackStore=null;}if(placeStore!=null){placeStore.close();placeStore=null;}super.onDetachedFromWindow();}
}
